def program(slug, days, ru, en, img, acts_ru=(), acts_en=(), group=None, private=None, dates=None, layer=None, plan_ru=None, plan_en=None):
    return {"slug": slug, "days": days, "img": img, "layer": layer, "stops": STOPS.get(slug, []),
            "ru": {"name": ru, "acts": list(acts_ru), "plan": plan_ru or []}, "en": {"name": en, "acts": list(acts_en), "plan": plan_en or []},
            "group": group or {}, "private": private or {}, "dates": dates or []}

